// --- FILTRE STRICT ANTI-DOUBLONS ---

const emails = $items("Gmail Trigger");
const allLabels = $items("2. Get All Labels");

// On isole les IDs de vos labels perso
const userLabelIds = allLabels
  .filter(l => l.json.type === 'user')
  .map(l => l.json.id);

// On ne garde que les emails SANS label perso
const filteredEmails = emails.filter(item => {
  const emailLabels = item.json.labelIds || [];
  const isAlreadyLabeled = emailLabels.some(id => userLabelIds.includes(id));
  return !isAlreadyLabeled;
});

// Préparation pour l'IA
return filteredEmails.map(item => {
  const json = item.json;
  return {
    json: {
      email_id: json.id,
      snippet: json.snippet,
      subject: json.subject || 'No Subject',
      sender: json.from || 'Unknown'
    }
  }
});

// Match & Filter (Version Finale)
const itemJson = $input.item.json;
let decisionLabel = "Divers";
let targetId = null;

// 1. Lecture de la réponse IA
if (itemJson.label_name) {
  decisionLabel = itemJson.label_name;
  targetId = itemJson.email_id;
} 
else if (itemJson.text) {
  const cleanJson = itemJson.text.replace(/```json/g, '').replace(/```/g, '').trim();
  try {
    const parsed = JSON.parse(cleanJson);
    if (parsed.label_name) decisionLabel = parsed.label_name;
    if (parsed.email_id) targetId = parsed.email_id;
  } catch (e) {}
}

decisionLabel = decisionLabel ? decisionLabel.trim() : "Divers";

// 2. Recherche du label
const allLabels = $items("2. Get All Labels");
let matchLabel = allLabels.find(l => l.json.name.toLowerCase() === decisionLabel.toLowerCase());

// Fallback sur Divers
if (!matchLabel) {
    matchLabel = allLabels.find(l => l.json.name.toLowerCase() === "divers");
}

// 3. Sécurité
if (!matchLabel || !targetId) {
    return [];
}

return {
  json: {
    email_id: targetId,
    label_id: matchLabel.json.id,
    applied_label: matchLabel.json.name
  }
};
